//! DTS Coherent Acoustics' tables, from ETSI TS 102 114 V1.6.1 annex D, made
//! by a script. The spec's Table D65 lacks its last four rows and its D129
//! says 37 for -37; FFmpeg's agree with the spec's elsewhere and gave those.
//! The two tables the spec leaves out are in `vq.zig`.

/// A Huffman code: its quantization level, length and bits.
pub const Code = struct { level: i16, length: u8, bits: u16 };

/// A code book as a binary tree: at each node a bit chooses a child, the
/// next node, or below 0 a leaf: `leaf_bias` less its level.
pub const Tree = []const [2]i16;
pub const leaf_bias = 128;

/// A code book's tree, made at compile time.
fn tree(comptime codes: []const Code) Tree {
    return &struct {
        const nodes = blk: {
            @setEvalBranchQuota(1000000);
            var made: [codes.len - 1][2]i16 = undefined;
            var used: usize = 1;
            made[0] = .{ 0, 0 };
            for (codes) |code| {
                var at: usize = 0;
                var left: usize = code.length;
                while (left > 1) : (left -= 1) {
                    const bit = (code.bits >> (left - 1)) & 1;
                    if (made[at][bit] == 0) {
                        made[used] = .{ 0, 0 };
                        made[at][bit] = used;
                        used += 1;
                    }
                    at = made[at][bit];
                }
                made[at][code.bits & 1] = -(code.level + leaf_bias);
            }
            const final = made;
            break :blk final;
        };
    }.nodes;
}

